# Move a claim to another person on the sheet (a steward's): only a DRAFT, OPEN or PENDING claim moves. It keeps its
# number and date, is unbound from any statement figure and is listed as its new person's newest claim.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: reassign
reassign:
  class: net.officefloor.hq.app.claim.ValidateReassign
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.claim.RefuseClosedClaim
  govern: [ transaction ]
  next: rollup-before
rollup-before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyReassign
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimReassigned
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to another person on the sheet: by a role the sheet's reassign permission gives (a steward's while blank), and only for a DRAFT, OPEN or PENDING claim, never to its
 * own person nor to one retired before the claim's date. It keeps its number and date, loses any figure a statement
 * bound it to (live again until its new person's next statement) and is listed as its new person's newest claim.
 */
public class ApplyReassign {
    public void apply(@Val ReassignTo to, @Val Claim claim, @Val ChangedBy by, ClaimRepository repository,
            PersonRepository people, RoleRepository roles, SettingRepository settings) throws BadRequestException {
        String sheetId = claim.getSheetId();
        String role = roles.roleOf(sheetId, by.name());
        if (!settings.allows(sheetId, "reassign", role)) {
            throw new BadRequestException("A " + role + " may not move a claim to another person on this sheet");
        }
        ClaimStatus status = claim.getStatus();
        if (status != ClaimStatus.DRAFT && !status.isOpen()) {
            throw new BadRequestException("A " + status + " claim cannot move to another person");
        }
        Person target = people.find(sheetId, to.personId());
        if (target == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        if (target.getId() == claim.getPersonId()) {
            throw new BadRequestException("The claim is already that person's");
        }
        RefuseRetiredDate.refuse(target, claim.getDate());
        Person from = people.find(sheetId, claim.getPersonId());
        if (!repository.reassign(claim, target.getId())) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
        to.moved(from == null ? "" : from.getName(), target.getName());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The person a claim is to move to. Publishes it with the user making the change. */
public class ValidateReassign {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignTo> to, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        if (request == null || request.personId() == null) {
            throw new BadRequestException("Choose the person to move the claim to");
        }
        to.set(new ReassignTo(request.personId()));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.claim;

/** The id of the person a claim is to move to; once moved, the names it moved from and to, for the audit. */
public class ReassignTo {

    private final long personId;
    private String fromName;
    private String toName;

    public ReassignTo(long personId) {
        this.personId = personId;
    }

    public long personId() {
        return personId;
    }

    public String fromName() {
        return fromName;
    }

    public String toName() {
        return toName;
    }

    void moved(String fromName, String toName) {
        this.fromName = fromName;
        this.toName = toName;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordClaimReassigned {
    public void record(@Val Claim claim, @Val ReassignTo to, @Val ChangedBy by, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_REASSIGNED", claim, by, to.toName()) + " from=" + to.fromName() + " to="
                + to.toName());
    }
}
    /**
     * Move the claim from {@code from} to its status, number, settled due and opener. Whether it was still {@code from}:
     * the row is locked by the first of two users changing it, so the other one finds it moved.
     */
    public boolean updateStatus(Claim claim, ClaimStatus from) {
        return jdbc.update("UPDATE claim SET status = ?, claim_number = ?, settled_due = ?, opened_by = ?, void_reason = ? WHERE id = ? AND status = ?",
                claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getVoidReason(), claim.getId(), from.name()) == 1;
    }

    /**
     * Move the claim to its person, unbound from any statement figure and listed as that person's newest claim. Whether
     * it was still in its status: the first of two users changing it locks the row, so the other one finds it moved.
     */
    public boolean reassign(Claim claim, long personId) {
        boolean moved = jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, listed = ?"
                + " WHERE id = ? AND status = ?", personId, nextListed(claim.getSheetId()), claim.getId(),
                claim.getStatus().name()) == 1;
        if (moved) {
            claim.moveTo(personId);
        }
        return moved;
    }

    /** Take the sheet's next listing key: a claim added or moved is listed before every claim listed earlier. */
    private long nextListed(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE "
                + "(UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)", Long.class, sheetId);
    }

    /** Take the sheet's next claim number, in one statement so two users never get the same one. */
    public int nextNumber(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE "
                + "(UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)", Integer.class, sheetId);
    }

    /** Take the next number of one of the sheet's per-period sequences (a period's id, or X for no period), from 1. */
    public int nextNumber(String sheetId, String sequence) {
        try {
            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key) SELECT ?, ? FROM DUAL WHERE NOT EXISTS"
                    + " (SELECT 1 FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?)", sheetId, sequence, sheetId, sequence);
        } catch (org.springframework.dao.DuplicateKeyException started) {
            // another user started it first
        }
        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE (UPDATE claim_sequence SET last_number = last_number + 1"
                + " WHERE sheet_id = ? AND seq_key = ?)", Integer.class, sheetId, sequence);
    }
}
